/**
 * A subclass of the Struts 2 `ActionSupport` class.
 */
class Struts2ActionSupportClass extends Class {
  Struts2ActionSupportClass() {
    this.getASourceSupertype+().hasQualifiedName("com.opensymphony.xwork2", "ActionSupport")
  }

  /**
