/** Holds if `n1` is the qualifier of a call to `clone()` and `n2` is the result. */
predicate cloneStep(Node n1, Node n2) {
  exists(MethodCall mc |
    mc.getMethod() instanceof CloneMethod and
    n1 = getInstanceArgument(mc) and
    n2.asExpr() = mc
