    exists(ClassInstanceExpr cie |
      cie.getConstructedType() instanceof TypeIntent and
      cie.getArgument(0).getType() instanceof TypeIntent
    |
      node1.asExpr() = cie.getArgument(0) and
      node2.asExpr() = cie
    )
